  /* ---------------- 投流情况 ---------------- */
  function boostKey(order) {
    var clean = order.replace(/\n/g, " ").replace(/\s*短视频加热.*$/i, "").trim();
    var normalized = clean.replace(/[\s，。！？#、:：!！,.?]/g, "");
    for (var i = 0; i < VIDEO.length; i++) {
      var title = VIDEO[i].title.replace(/[\s，。！？#、:：!！,.?]/g, "");
      if (normalized.indexOf(title.slice(0, Math.min(16, title.length))) >= 0) return VIDEO[i].title;
    }
    return clean || order.replace(/\n/g, " ");
  }
  function chineseCore(text) {
    return (text.match(/[\u4e00-\u9fff]/g) || []).join("");
  }
  function findSimilarBoostKey(key, map) {
    var core = chineseCore(key); if (core.length < 6) return key;
    var keys = Object.keys(map), best = key, bestScore = 0;
    keys.forEach(function (existing) {
      var other = chineseCore(existing); if (other.length < 6) return;
      var prefix = 0, limit = Math.min(core.length, other.length);
      while (prefix < limit && core[prefix] === other[prefix]) prefix++;
      var set = {}; other.split("").forEach(function (c) { set[c] = true; });
      var shared = core.split("").filter(function (c) { return set[c]; }).length;
      var score = Math.max(prefix / limit, shared / Math.max(core.length, other.length));
      if (score >= 0.62 && score > bestScore) { best = existing; bestScore = score; }
    });
    return best;
  }
  var boostAggMap = {};
  BOOST.forEach(function (x) {
    var rawKey = boostKey(x.order), key = findSimilarBoostKey(rawKey, boostAggMap), amountMatch = String(x.progress).match(/([\d.]+)\s*\/\s*[\d.]+/), amount = amountMatch ? parseFloat(amountMatch[1]) / 10 : 0;
    if (!boostAggMap[key]) boostAggMap[key] = { title: key, count: 0, amount: 0, plays: 0, completionTotal: 0, completionCount: 0, created: x.created, status: x.status };
    var a = boostAggMap[key]; a.count++; a.amount += amount; a.plays += x.plays; if (x.created > a.created) a.created = x.created; if (parseFloat(x.completion)) { a.completionTotal += parseFloat(x.completion); a.completionCount++; }
  });
  var boostAgg = Object.keys(boostAggMap).map(function (k) { var a = boostAggMap[k]; a.completion = a.completionCount ? (a.completionTotal / a.completionCount).toFixed(2) + "%" : "-"; return a; }).sort(function (a, b) { return b.amount - a.amount; });
  var boostCountTotal = sum(boostAgg, function (x) { return x.count; });
