  var boostAvg = boostAgg.length ? (boostAgg.reduce(function (s, x) { return s + (x.completionCount ? parseFloat(x.completion) : 0); }, 0) / boostAgg.length).toFixed(2) : "0";
  $("#boostSummary").innerHTML = '<div class="boostKpi"><span>投流次数</span><strong>' + fmt(boostCountTotal) + ' 次</strong></div>' + '<div class="boostKpi"><span>投流总金额</span><strong>¥' + boostAmount.toFixed(1) + '</strong></div>' + '<div class="boostKpi"><span>投流带来播放</span><strong>' + fmt(boostPlays) + '</strong></div>';
  var boostPageSize = 5, boostPage = 1;
  function renderBoostPage() { var total = Math.max(1, Math.ceil(boostAgg.length / boostPageSize)); boostPage = Math.max(1, Math.min(boostPage, total)); var view = boostAgg.slice((boostPage - 1) * boostPageSize, boostPage * boostPageSize); $("#boostBody").innerHTML = view.map(function (x) { return '<tr><td>' + x.title + '</td><td>' + fmt(x.count) + ' 次</td><td class="green">¥' + x.amount.toFixed(1) + '</td><td>' + fmt(x.plays) + '</td><td>' + x.completion + '</td></tr>'; }).join(""); $("#boostCount").textContent = "共 " + boostAgg.length + " 个视频"; $("#boostPager").innerHTML = '<button data-boost="prev" '+(boostPage===1?'disabled':'')+'>‹</button>'+Array.from({length:total},function(_,i){return '<button data-boost="'+(i+1)+'" class="'+(i+1===boostPage?'active':'')+'">'+(i+1)+'</button>';}).join('')+'<button data-boost="next" '+(boostPage===total?'disabled':'')+'>›</button>'; }
  renderBoostPage();
  $("#boostPager").addEventListener("click", function(e){var b=e.target.closest("button");if(!b)return;var v=b.dataset.boost;if(v==='prev')boostPage--;else if(v==='next')boostPage++;else boostPage=+v;renderBoostPage();});

